    B.LegalSection_vcX = new A.LegalSection("\u0661. \u0645\u064a\u0646 \u0625\u062d\u0646\u0627", "xStore \u062a\u0634\u063a\u0651\u0644 \u062a\u0637\u0628\u064a\u0642 \u0627\u0644\u0633\u0648\u0642. \u062d\u0633\u0628 \u0642\u0627\u0646\u0648\u0646 \u062d\u0645\u0627\u064a\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0634\u062e\u0635\u064a\u0629 \u0631\u0642\u0645 \u0661\u0665\u0661 \u0644\u0633\u0646\u0629 \u0662\u0660\u0662\u0660\u060c \u0625\u062d\u0646\u0627 \u0627\u0644\u0645\u062a\u062d\u0643\u0645 \u0641\u064a \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u062d\u0633\u0627\u0628 \u0648\u0627\u0644\u0637\u0644\u0628\u0627\u062a \u0627\u0644\u0644\u064a \u0628\u062a\u062f\u062e\u0644\u0647\u0627 \u0641\u064a \u0627\u0644\u062a\u0637\u0628\u064a\u0642.");
    B.LegalSection_Kep = new A.LegalSection("\u0662. \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0644\u064a \u0628\u0646\u062c\u0645\u0639\u0647\u0627", "\u0627\u0644\u062d\u0633\u0627\u0628: \u0627\u0644\u0627\u0633\u0645\u060c \u0627\u0644\u0625\u064a\u0645\u064a\u0644\u060c \u0631\u0642\u0645 \u0645\u0648\u0628\u0627\u064a\u0644 \u0645\u0635\u0631\u064a\u060c \u0627\u0644\u062f\u0648\u0631 (\u0645\u0634\u062a\u0631\u064a/\u0628\u0627\u0626\u0639)\u060c \u0648\u0643\u0644\u0645\u0629 \u0627\u0644\u0633\u0631 \u0623\u0648 \u062a\u0648\u0643\u0646 \u0627\u0644\u062f\u062e\u0648\u0644. \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0645\u0644\u0641 \u0648\u0627\u0644\u0645\u062a\u062c\u0631. \u0627\u0644\u0637\u0644\u0628\u0627\u062a: \u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u062a\u0648\u0635\u064a\u0644\u060c \u0645\u0648\u0628\u0627\u064a\u0644 \u0627\u0644\u0645\u0633\u062a\u0644\u0645\u060c \u0627\u0644\u0623\u0635\u0646\u0627\u0641\u060c \u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0627\u062a. \u0627\u0644\u062c\u0647\u0627\u0632: \u0625\u0635\u062f\u0627\u0631 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0648\u0627\u0644\u0644\u063a\u0629 \u0648\u0627\u0644\u0645\u0648\u0642\u0639 \u0627\u0644\u062a\u0642\u0631\u064a\u0628\u064a (\u062e\u0637\u0648\u0637 \u0637\u0648\u0644/\u0639\u0631\u0636 \u0639\u0634\u0627\u0646 \u0627\u0644\u0643\u062a\u0627\u0644\u0648\u062c \u0627\u0644\u0642\u0631\u064a\u0628 \u064a\u0634\u062a\u063a\u0644). \u0645\u0634 \u0628\u0646\u062c\u0645\u0639 \u0631\u0642\u0645 \u0628\u0637\u0627\u0642\u0629 \u0623\u0648 CVV \u0623\u0648 \u0628\u064a\u0627\u0646\u0627\u062a \u0628\u0646\u0643.");
    B.LegalSection_CdI = new A.LegalSection("\u0663. \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645", "\u062a\u0634\u063a\u064a\u0644 \u0627\u0644\u062d\u0633\u0627\u0628\u060c \u062a\u0623\u0643\u064a\u062f \u0627\u0644\u0645\u0648\u0628\u0627\u064a\u0644\u060c \u062a\u0646\u0641\u064a\u0630 \u0637\u0644\u0628\u0627\u062a \u0627\u0644\u0643\u0627\u0634 \u0639\u0646\u062f \u0627\u0644\u0627\u0633\u062a\u0644\u0627\u0645\u060c \u0639\u0631\u0636 \u0627\u0644\u0625\u0639\u0644\u0627\u0646\u0627\u062a \u0627\u0644\u0645\u0646\u0627\u0633\u0628\u0629\u060c \u0625\u0634\u0639\u0627\u0631\u0627\u062a \u0627\u0644\u0637\u0644\u0628\u060c \u0648\u0645\u0646\u0639 \u0627\u0644\u0627\u062d\u062a\u064a\u0627\u0644. \u0627\u0644\u0645\u0648\u0642\u0639 \u0627\u0644\u062a\u0642\u0631\u064a\u0628\u064a \u0644\u0644\u0643\u062a\u0627\u0644\u0648\u062c \u0645\u0634 \u0644\u0644\u0625\u0639\u0644\u0627\u0646\u0627\u062a.");
    B.LegalSection_oaK = new A.LegalSection("\u0664. \u0627\u0644\u0645\u0634\u0627\u0631\u0643\u0629", "\u0639\u0646\u062f \u0627\u0644\u0637\u0644\u0628\u060c \u0627\u0644\u0628\u0627\u0626\u0639 \u0628\u064a\u0627\u062e\u062f \u0627\u0644\u0644\u064a \u064a\u062d\u062a\u0627\u062c\u0647 \u0644\u0644\u062a\u0648\u0635\u064a\u0644 (\u0627\u0644\u0627\u0633\u0645\u060c \u0627\u0644\u0639\u0646\u0648\u0627\u0646\u060c \u0627\u0644\u0645\u0648\u0628\u0627\u064a\u0644\u060c \u0627\u0644\u0623\u0635\u0646\u0627\u0641). \u0627\u0644\u0645\u0646\u062f\u0648\u0628 \u0628\u064a\u0627\u062e\u062f \u0628\u064a\u0627\u0646\u0627\u062a\u0647 \u0628\u0639\u062f \u062a\u0623\u0643\u064a\u062f \u0627\u0644\u0637\u0644\u0628. \u0628\u0646\u0633\u062a\u062e\u062f\u0645 \u062e\u062f\u0645\u0627\u062a \u0627\u0633\u062a\u0636\u0627\u0641\u0629 \u0648\u062a\u0633\u062c\u064a\u0644 \u0648\u0625\u0634\u0639\u0627\u0631\u0627\u062a (\u0645\u062b\u0644 Firebase). \u0645\u0634 \u0628\u0646\u0628\u064a\u0639 \u0628\u064a\u0627\u0646\u0627\u062a\u0643.");
